"""Collapsible list of the gallery records generated by the selected AI Effect."""

from __future__ import annotations

from PySide6.QtCore import QEvent, QSize, Qt
from PySide6.QtGui import QIcon, QPixmap
from PySide6.QtWidgets import (
    QApplication,
    QDockWidget,
    QHBoxLayout,
    QListWidget,
    QListWidgetItem,
    QPushButton,
    QToolButton,
    QVBoxLayout,
    QWidget,
)

from loomstroke.plugins.ai_effect.gallery_bridge import matches_source_layer
from loomstroke.ui.translations import translated_literal_domain

GALLERY_PANEL_ID = "ui.gallery"
_THUMB = QSize(64, 64)


def tr(source: str) -> str:
    return translated_literal_domain("LayerGenerationHistory", source, use_fallback=True)


class LayerGenerationHistory(QWidget):
    """Newest-first thumbnails of ``store`` records whose source is ``layer_id``."""

    def __init__(self, store, layer_id: str, layer_name: str, host, parent=None):
        super().__init__(parent)
        self.store = store
        self.layer_id = layer_id
        self.layer_name = layer_name
        self.host = host
        layout = QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        self.header = QToolButton(self)
        self.header.setObjectName("aiLayerHistoryHeader")
        self.header.setCheckable(True)
        self.header.setToolButtonStyle(Qt.ToolButtonStyle.ToolButtonTextBesideIcon)
        self.header.setAutoRaise(True)
        layout.addWidget(self.header)
        self.body = QWidget(self)
        body = QVBoxLayout(self.body)
        body.setContentsMargins(0, 0, 0, 0)
        self.list = QListWidget(self.body)
        self.list.setObjectName("aiLayerHistoryList")
        self.list.setViewMode(QListWidget.ViewMode.IconMode)
        self.list.setFlow(QListWidget.Flow.LeftToRight)
        self.list.setWrapping(False)
        self.list.setMovement(QListWidget.Movement.Static)
        self.list.setIconSize(_THUMB)
        self.list.setFixedHeight(_THUMB.height() + 40)
        body.addWidget(self.list)
        actions = QHBoxLayout()
        self.show_button = QPushButton(self.body)
        self.show_button.setObjectName("aiLayerHistoryShow")
        self.open_button = QPushButton(self.body)
        self.open_button.setObjectName("aiLayerHistoryOpen")
        actions.addWidget(self.show_button)
        actions.addWidget(self.open_button)
        body.addLayout(actions)
        layout.addWidget(self.body)
        self.header.toggled.connect(self._set_expanded)
        self.list.currentItemChanged.connect(lambda *_: self._update_enabled())
        self.list.itemDoubleClicked.connect(lambda _item: self.show_selected())
        self.show_button.clicked.connect(self.show_selected)
        self.open_button.clicked.connect(self.open_filtered)
        store.record_added.connect(self._on_store_changed)
        store.record_updated.connect(self._on_store_changed)
        store.record_removed.connect(self._on_store_changed)
        store.records_loaded.connect(self.refresh)
        self._set_expanded(False)
        self.refresh()

    def records(self) -> list:
        return [r for r in self.store.list_records() if matches_source_layer(r, self.layer_id)]

    def refresh(self) -> None:
        current = self.selected_job_id()
        self.list.clear()
        base = self.store.base_path
        records = self.records()
        for record in records:
            item = QListWidgetItem(record.created_at[11:16] if len(record.created_at) > 16 else "")
            item.setData(Qt.ItemDataRole.UserRole, record.job_id)
            item.setToolTip(record.prompt or "")
            if record.thumbnail_path and (base / record.thumbnail_path).exists():
                item.setIcon(QIcon(QPixmap(str(base / record.thumbnail_path))))
            self.list.addItem(item)
            if record.job_id == current:
                self.list.setCurrentItem(item)
        self._count = len(records)
        self.retranslate()

    def _on_store_changed(self, _job_id: str) -> None:
        self.refresh()

    def selected_job_id(self) -> str | None:
        item = self.list.currentItem()
        return item.data(Qt.ItemDataRole.UserRole) if item is not None else None

    def show_selected(self) -> None:
        """Reveal the selected record in the Gallery panel."""
        job_id = self.selected_job_id()
        gallery = self._open_gallery()
        if gallery is not None and job_id:
            gallery.select_record(job_id)

    def open_filtered(self) -> None:
        """Open the Gallery panel limited to this layer's records."""
        gallery = self._open_gallery()
        if gallery is not None:
            gallery.set_layer_filter(self.layer_id, self.layer_name)

    def _open_gallery(self):
        from loomstroke.ui.panels.gallery_panel import GalleryPanel  # noqa: PLC0415

        setter = getattr(self.host, "set_panel_visible", None)
        if callable(setter):
            setter(GALLERY_PANEL_ID, True)
        # The shared Gallery sits directly in its dock; plugin panels embed
        # their own service-filtered copies deeper in their layouts.
        for window in QApplication.topLevelWidgets():
            for dock in [window, *window.findChildren(QDockWidget)]:
                panel = dock.widget() if isinstance(dock, QDockWidget) else None
                if isinstance(panel, GalleryPanel):
                    dock.raise_()
                    return panel
        return None

    def _set_expanded(self, expanded: bool) -> None:
        self.header.setArrowType(Qt.ArrowType.DownArrow if expanded else Qt.ArrowType.RightArrow)
        self.body.setVisible(expanded)

    def _update_enabled(self) -> None:
        self.show_button.setEnabled(self.selected_job_id() is not None)
        self.open_button.setEnabled(self._count > 0)

    def retranslate(self) -> None:
        self.header.setText(tr("Generated on this layer ({count})").format(count=self._count))
        self.show_button.setText(tr("Show in Gallery"))
        self.open_button.setText(tr("Open in Gallery (this layer only)"))
        self.list.setToolTip("" if self._count else tr("No generations yet."))
        self._update_enabled()

    def changeEvent(self, event: QEvent) -> None:  # noqa: N802
        super().changeEvent(event)
        if event.type() == QEvent.Type.LanguageChange:
            self.retranslate()


def mount(section, layout, layer_id: str | None) -> None:
    """Add the history list under the action bar when a history store exists."""
    host = section._host
    getter = getattr(host, "get_service", None)
    store = getter("generation_history") if callable(getter) and layer_id else None
    if store is None:
        return
    canvas = getattr(host, "canvas", None)
    finder = getattr(canvas, "_find_layer_by_id_tree", None)
    layer = finder(layer_id) if callable(finder) else None
    name = str(getattr(layer, "name", "") or layer_id)
    widget = LayerGenerationHistory(store, layer_id, name, host, section._ai_effect_group)
    # Keep the open/closed choice while the user moves between layers.
    widget.header.setChecked(bool(getattr(section, "_layer_history_expanded", False)))
    widget.header.toggled.connect(lambda on: setattr(section, "_layer_history_expanded", on))
    layout.addWidget(widget)
